<?php $pageTitle='Faculty availability'; ?><section class="page-heading"><div><p class="eyebrow">Invigilation preparation</p><h1>Faculty availability</h1><p>Unavailable faculty are excluded from automatic allocation for the selected examination session.</p></div><a class="secondary-button" href="<?= e(url('faculty')) ?>">Back to faculty</a></section><?php if($success):?><div class="alert success"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error"><?= e($error) ?></div><?php endif;?><section class="split-workspace"><form class="panel quick-form" method="post" action="<?= e(url('faculty/availability')) ?>"><?= csrf_field() ?><h2>Set availability</h2><label>Faculty<select name="faculty_id" required><?php foreach($faculty as $f):?><option value="<?= (int)$f['id'] ?>"><?= e($f['employee_id'].' - '.$f['name']) ?></option><?php endforeach;?></select></label><label>Date<input type="date" name="exam_date" required></label><label>Shift<select name="shift_id" required><?php foreach($shifts as $s):?><option value="<?= (int)$s['id'] ?>"><?= e($s['cycle_name'].' - '.$s['name'].' '.substr($s['start_time'],0,5)) ?></option><?php endforeach;?></select></label><label>Availability<select name="availability"><option value="available">Available</option><option value="preferred">Preferred</option><option value="unavailable">Unavailable</option></select></label><label>Reason<input name="reason"></label><button class="primary-button">Save availability</button></form><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Date</th><th>Cycle / Shift</th><th>Faculty</th><th>Availability</th><th>Reason</th></tr></thead><tbody><?php foreach($entries as $entry):?><tr><td><?= e(date('d M Y',strtotime($entry['exam_date']))) ?></td><td><?= e($entry['cycle_name'].' / '.$entry['shift_name']) ?></td><td><?= e($entry['employee_id'].' - '.$entry['faculty_name']) ?></td><td><span class="status-label <?= e($entry['availability']) ?>"><?= e(ucfirst($entry['availability'])) ?></span></td><td><?= e($entry['reason']) ?></td></tr><?php endforeach;?></tbody></table></div></section></section>
